BEGIN TRANSACTION;
CREATE TABLE jobs (
                reference_number TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                department TEXT,
                location TEXT,
                salary TEXT,
                closing_date TEXT,
                job_url TEXT,
                logo_url TEXT,
                first_seen_at TEXT NOT NULL,
                last_scraped_at TEXT NOT NULL
            , salary_min INTEGER, salary_max INTEGER, job_grade TEXT, role_type TEXT, working_pattern TEXT, contract_type TEXT);
CREATE TABLE scrape_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                run_at TEXT NOT NULL,
                mode TEXT NOT NULL,
                pages_scraped INTEGER DEFAULT 0,
                jobs_found INTEGER DEFAULT 0,
                new_jobs_added INTEGER DEFAULT 0,
                duration_seconds REAL DEFAULT 0.0,
                status TEXT DEFAULT 'success',
                error_message TEXT
            );
CREATE INDEX idx_jobs_dept ON jobs(department);
CREATE INDEX idx_jobs_first_seen ON jobs(first_seen_at);
CREATE INDEX idx_jobs_closing ON jobs(closing_date);
CREATE INDEX idx_logs_run_at ON scrape_logs(run_at);
CREATE INDEX idx_jobs_salary_min ON jobs(salary_min);
CREATE INDEX idx_jobs_salary_max ON jobs(salary_max);
CREATE INDEX idx_jobs_grade ON jobs(job_grade);
CREATE INDEX idx_jobs_role ON jobs(role_type);
CREATE INDEX idx_jobs_contract ON jobs(contract_type);
CREATE INDEX idx_jobs_pattern ON jobs(working_pattern);
DELETE FROM "sqlite_sequence";
COMMIT;
